return {["BENEATH"]={["title"]="THE SPARE ROOM v3.0.0 — BENEATH THE HOUSE",["tagline"]="There was always something underneath.",["rooms"]={{["id"]="storage",["name"]="Storage Room",["purpose"]="Unpack a history nobody labelled.",["set"]="Dusty shelves, folded blankets, a travel trunk and a ledger of boxes.",["contradiction"]="The handwriting on a recent box matches an old school label.",["progression"]="Inventory boxes; find the archive key.",["side"]=-1,["row"]=0},{["id"]="boiler",["name"]="Boiler Room",["purpose"]="Give the house a rhythm that is not a voice.",["set"]="Copper pipes, pressure gauges, condensate, a service bench and an isolated valve.",["contradiction"]="Four branches are labelled BEDROOM. The house has fewer bedrooms.",["progression"]="Choose whether to stop the knocking pipe or keep its rhythm.",["side"]=1,["row"]=0},{["id"]="tunnel",["name"]="Maintenance Tunnel",["purpose"]="Follow domestic repairs into unfamiliar space.",["set"]="Narrow service racks, cable trays, wall access panels and a measured central route.",["contradiction"]="A maintenance distance is longer on the return journey.",["progression"]="Mark a route and recover the observation key.",["side"]=-1,["row"]=1},{["id"]="archive",["name"]="Archive Room",["purpose"]="Compare records without assuming they are reliable.",["set"]="Flat files, labelled archive boxes, school registers and a family index.",["contradiction"]="Two originals carry the same document number and different household totals.",["progression"]="Use the storage key; compare the conflicting records; find the study key.",["side"]=1,["row"]=1},{["id"]="family",["name"]="Forgotten Family Room",["purpose"]="Recognise habits before recognising faces.",["set"]="An ordinary sofa, a low table, extra chairs, a cardigan and an unplugged radio.",["contradiction"]="The furniture is worn where no one is supposed to have sat.",["progression"]="Lay out photographs, set places and listen to the radio.",["side"]=-1,["row"]=2},{["id"]="study",["name"]="Hidden Study",["purpose"]="Encounter the possibility of Dad through his work.",["set"]="Drafting tools, unfinished letters, a desk lamp and a chair facing away from the door.",["contradiction"]="One letter is signed Dad; another matching draft is unsigned.",["progression"]="Use the archive key; assemble and choose what to do with the drafts.",["side"]=1,["row"]=2},{["id"]="sealed",["name"]="Sealed Corridor",["purpose"]="Reach an omission somebody took care to preserve.",["set"]="Bricked door outlines, inspection tags, chalk measurements and a single accessible doorway.",["contradiction"]="Room numbers skip a number twice, in different places.",["progression"]="Isolate the noisy pipe and use the observation key.",["side"]=-1,["row"]=3},{["id"]="observation",["name"]="Observation Room",["purpose"]="Question who was studying whom.",["set"]="An internal window, an empty recording desk and chairs facing the family room.",["contradiction"]="A report describes the observer using the player’s childhood nickname.",["progression"]="Use the tunnel key; compare the glass, log and empty tape spool.",["side"]=1,["row"]=3},{["id"]="children",["name"]="Former Children’s Area",["purpose"]="Find the traces of more than one childhood.",["set"]="Two narrow bed frames, low hooks, a drawing wall, height marks and a toy shelf.",["contradiction"]="Three height columns have two dates. The pencil heights do not fit the dates.",["progression"]="Match drawings and height marks; discover the chamber key.",["side"]=-1,["row"]=4},{["id"]="chamber",["name"]="Locked Chamber",["purpose"]="Find a question that resists becoming an answer.",["set"]="A plain room, two chairs, an unfinished family inventory and an unpowered door mechanism.",["contradiction"]="Its inventory describes furniture the player has just moved elsewhere.",["progression"]="Use the chamber key, twelve diary entries and three family records. Make an interpretation, not a revelation.",["side"]=1,["row"]=4}},["diary"]={{["id"]="diary1",["number"]=1,["title"]="The long table",["text"]="Mum made toast and Dad drew a boat in the butter. We argued about who got the crooked slice. I counted four cups before anyone sat down. I am writing that because I always forget ordinary things."},{["id"]="diary2",["number"]=2,["title"]="Our marks",["text"]="We measured ourselves by the kitchen door. Mine is the bent line. The straight one belongs to the person who insists they are taller. Dad wrote the date twice because the first date looked wrong."},{["id"]="diary3",["number"]=3,["title"]="Saturday rain",["text"]="We made a tent from two sheets. Mum said not to block the hallway. Someone kept putting a fourth cushion inside. We left it there. It made a good roof support."},{["id"]="diary4",["number"]=4,["title"]="The school photograph",["text"]="Our class photographs came home. There are two envelopes with our surname and one with no name. Mum put the empty one in the drawer before I could see whether it was empty."},{["id"]="diary5",["number"]=5,["title"]="Dad’s coat",["text"]="Dad let me carry his coat upstairs. It smelled of rain and the workshop. The pockets were full of small screws. One pocket had a key labelled RETURN, though I do not know what it returns."},{["id"]="diary6",["number"]=6,["title"]="The other bed",["text"]="We swapped beds after the argument about the window. In the morning everybody said there had only ever been one bed. The floor is still lighter where the other feet stood."},{["id"]="diary7",["number"]=7,["title"]="The room at the end",["text"]="There is a room at the end of the hall. I thought it belonged to our visitor. Nobody remembers inviting a visitor. Mum told me to leave the clean towel outside it anyway."},{["id"]="diary8",["number"]=8,["title"]="Knocking practice",["text"]="Three knocks mean come in. Two mean wait. Tonight someone knocked twice from the wall beside my pillow. I waited. It seems rude to leave someone waiting, even if there is no door."},{["id"]="diary9",["number"]=9,["title"]="A quiet argument",["text"]="Dad said keeping a room was not the same as keeping a person. Mum said he had agreed before. They stopped when I entered. There were four unfinished cups on the table, all still warm."},{["id"]="diary10",["number"]=10,["title"]="The spare name",["text"]="My report has a name crossed out beneath mine. The teacher says she never wrote it. Her pen left the same little hook on every letter. I have copied the hook here so it cannot disappear."},{["id"]="diary11",["number"]=11,["title"]="Yesterday’s drawing",["text"]="My drawing has changed. I remember giving the tall person five fingers. Now the tall person is a door, but the hand is still there. Mum says I have always drawn buildings."},{["id"]="diary12",["number"]=12,["title"]="Someone’s birthday",["text"]="We lit candles without a cake. Mum said it was not a birthday. Dad could not remember why he had bought the candles. There are marks on the table from a cake tin that will not fit our cupboard."},{["id"]="diary13",["number"]=13,["title"]="The missing pronoun",["text"]="I wrote WE WENT HOME. This morning it says I WENT HOME. The space is too wide for I. I keep trying to remember whose hand I was holding, and remembering a different sleeve."},{["id"]="diary14",["number"]=14,["title"]="A longer landing",["text"]="It took seventeen steps to reach the bathroom. I counted twelve on the way back. Dad marked the wall with tape. In the evening the tape was wrapped around his wrist like he had always worn it."},{["id"]="diary15",["number"]=15,["title"]="The voice downstairs",["text"]="Someone read my first page aloud from underneath the floor. They made the same mistake over the word crooked. I do not remember writing that mistake. I do remember being corrected."},{["id"]="diary16",["number"]=16,["title"]="Our own handwriting",["text"]="There are two kinds of handwriting in this book. The second kind calls the first kind a liar. Both make the same spelling mistakes. I am leaving the mistakes where they are."},{["id"]="diary17",["number"]=17,["title"]="The person in the photograph",["text"]="Dad is missing from one photograph. In the next he is holding the camera, though I can see both his hands in the picture. Mum knows which coat was his. She cannot say what he looked like."},{["id"]="diary18",["number"]=18,["title"]="A room set aside",["text"]="We carried boxes to the room that is not on the plan. I remember doing it alone. My arms hurt in four places, as if someone else had been holding the same box."},{["id"]="diary19",["number"]=19,["title"]="If you find this",["text"]="If you find this, do not decide too quickly who I was. I have been your sibling in some memories and your visitor in others. The room remembers a name. It will not tell me whether the name was mine."},{["id"]="diary20",["number"]=20,["title"]="An ordinary morning",["text"]="Today we had toast. Someone asked for the crooked slice. There were places for everybody, which is not the same as knowing how many people there were. Please leave this page unfinished. I would like tomorrow to have somewhere to go."}},["anomalies"]={{["id"]="portrait",["name"]="The Removed Face",["room"]="family",["description"]="A photograph loses one silhouette, leaving a clean patch rather than a torn surface.",["visual"]="A frame alternates between three and four silhouettes only after the player looks away.",["interaction"]="Inspect both versions; record a contradiction, not a name."},{["id"]="chair",["name"]="One More Place",["room"]="family",["description"]="A fourth chair appears at the table. Its legs are free of dust.",["visual"]="A spare chair is enabled behind the player after a turn.",["interaction"]="Count the chairs and inspect the extra seat."},{["id"]="names",["name"]="Carbon Names",["room"]="archive",["description"]="Names emerge on a blank carbon sheet, then overlap.",["visual"]="A document label reveals an additional line in oblique light.",["interaction"]="Read before and after switching the desk lamp."},{["id"]="breath",["name"]="Breathing Plaster",["room"]="sealed",["description"]="The wall expands by a few centimetres with the boiler rhythm.",["visual"]="A bounded wall inset scales slowly; collision stays fixed.",["interaction"]="Watch a full cycle from a safe distance."},{["id"]="drawer",["name"]="The Returning Drawer",["room"]="study",["description"]="A shut drawer reopens with a different small possession inside.",["visual"]="A drawer slides back within its desk footprint.",["interaction"]="Close it twice and inspect the returned object."},{["id"]="ink",["name"]="A Second Report",["room"]="archive",["description"]="A school report adds another pupil using the same registration number.",["visual"]="A second report plane appears beside the first.",["interaction"]="Compare the two copies."},{["id"]="clock",["name"]="The Uncounted Minute",["room"]="boiler",["description"]="A clock hand travels backwards while the pipe keeps time.",["visual"]="Clock hands reverse; world time continues normally.",["interaction"]="Listen through six ticks."},{["id"]="coat",["name"]="Small Shoulders",["room"]="storage",["description"]="A child’s coat lifts as if occupied, then hangs empty.",["visual"]="A cloth-shaped rig rises and settles without approaching.",["interaction"]="Look away and inspect the hook."},{["id"]="chalk",["name"]="The Taller Mark",["room"]="children",["description"]="A pencil height mark rises above the adult line.",["visual"]="One measured line slides upward within the board.",["interaction"]="Compare it with the school dates."},{["id"]="cups",["name"]="Still Warm",["room"]="family",["description"]="Steam rises from cups on an unpowered table.",["visual"]="Three pooled translucent wisps rise over four cups.",["interaction"]="Inspect the unconnected kettle."},{["id"]="steps",["name"]="The Other Footfall",["room"]="tunnel",["description"]="A second footstep continues after the player stops.",["visual"]="Two quiet beats and a caption trail the stopped player.",["interaction"]="Stand still until the extra step ends."},{["id"]="page",["name"]="Borrowed Page",["room"]="storage",["description"]="A diary page appears on a shelf after it was filed.",["visual"]="An apparition of a collected page appears; it cannot duplicate inventory.",["interaction"]="Inspect the apparition to record it."},{["id"]="shadow",["name"]="The Wrong Height",["room"]="children",["description"]="The player’s shadow has a child’s proportions.",["visual"]="A floor decal shortens while the camera and body stay unchanged.",["interaction"]="Watch the shadow without moving."},{["id"]="radio",["name"]="The Dinner Call",["room"]="family",["description"]="The disconnected radio counts places for dinner.",["visual"]="A radio dial glows and four quiet pulses play with captions.",["interaction"]="Listen without turning it on."},{["id"]="door",["name"]="The Inside Handle",["room"]="sealed",["description"]="A handle turns on the bricked outline of a door.",["visual"]="A brass handle rotates on a solid wall.",["interaction"]="Wait for it to stop; no traversable door is created."},{["id"]="boxes",["name"]="The Different Initials",["room"]="storage",["description"]="Boxes reorder their initials while the objects remain in place.",["visual"]="Three labels change once when unseen.",["interaction"]="Read two different arrangements."},{["id"]="glass",["name"]="The Occupied Reflection",["room"]="observation",["description"]="The glass shows occupied chairs where the real room is empty.",["visual"]="Faint stationary silhouettes appear behind the pane.",["interaction"]="Inspect the pane and the chairs."},{["id"]="pipe",["name"]="A Knock Returned",["room"]="boiler",["description"]="The pipe repeats a rhythm with one additional beat.",["visual"]="A valve wheel pulses in time with captioned tapping.",["interaction"]="Answer using the rhythm control."},{["id"]="drawing",["name"]="Five Windows",["room"]="children",["description"]="A drawing gains a window in a wall with no room behind it.",["visual"]="A fifth cut-out window lights up on the drawing board.",["interaction"]="Compare the drawing with the floor plan."},{["id"]="label",["name"]="Room Zero",["room"]="tunnel",["description"]="An inspection plate changes its room number to zero.",["visual"]="A small sign flips between two numbered faces.",["interaction"]="Inspect the plate after the flip."},{["id"]="lamp",["name"]="Someone Working",["room"]="study",["description"]="The desk lamp bends toward the empty chair.",["visual"]="An articulated lamp pivots slowly once.",["interaction"]="Stay outside the desk footprint and observe."},{["id"]="frost",["name"]="A Handprint Inside",["room"]="observation",["description"]="A warm palm-shaped clearing appears on the far side of cold glass.",["visual"]="A translucent handprint fades in behind the window.",["interaction"]="Inspect the far side without touching it."},{["id"]="scale",["name"]="The Long Return",["room"]="tunnel",["description"]="Perspective makes the exit seem farther away after turning.",["visual"]="Non-colliding repeated arch details compress visually; real route dimensions stay fixed.",["interaction"]="Walk to the original survey mark."},{["id"]="inventory",["name"]="Already Unpacked",["room"]="chamber",["description"]="An inventory lists the player’s current arrangement before it is made.",["visual"]="A document lists the flags last chosen in the family room.",["interaction"]="Compare the list with the family table."},{["id"]="lullaby",["name"]="The Missing Singer",["room"]="children",["description"]="An instrument plays a lullaby with a silent space where a voice should be.",["visual"]="A toy music wheel rotates through a captioned missing verse.",["interaction"]="Let the entire verse finish."}},["endings"]={{["id"]="places",["category"]="Family",["name"]="Places for Everyone",["requirements"]={["items"]={"photo1","photo2"},["flags"]={"places"}},["description"]="You set a place for every person suggested by the photographs. Mum adds one more cup, then sits down without explaining it.",["achievement"]="A Table Kept",["lore"]="Acknowledges possible relatives without assigning identities.",["number"]=32},{["id"]="coat-home",["category"]="Family",["name"]="The Coat at the Door",["requirements"]={["items"]={"dad1","photo3"},["flags"]={"letters"}},["description"]="You leave the coat where someone could collect it. In the morning it is dry. The hook is still warm.",["achievement"]="Expected Home",["lore"]="Dad remains an inference from belongings and drafts.",["number"]=33},{["id"]="two-beds",["category"]="Family",["name"]="Neither Bed Empty",["requirements"]={["items"]={"drawing1","drawing2"},["flags"]={"beds"}},["description"]="You make both beds. One mattress settles after the light goes out. You decide not to check which one.",["achievement"]="Room for Two",["lore"]="Supports a sibling reading while preserving uncertainty.",["number"]=34},{["id"]="ask-mum",["category"]="Family",["name"]="The Question at Breakfast",["requirements"]={["diary"]=6,["items"]={"record1"},["flags"]={"mum"}},["description"]="Mum listens to the names you found. She says she remembers the sound of them, but asks you not to supply the faces.",["achievement"]="Ask Gently",["lore"]="Mum is a witness with incomplete memories, not an exposition source.",["number"]=35},{["id"]="isolate",["category"]="Basement",["name"]="A Quiet Circuit",["requirements"]={["items"]={"dad2"},["flags"]={"valve","power"}},["description"]="The boiler stops knocking. Somewhere upstairs a chair is drawn back. The house has found another way to be heard.",["achievement"]="Circuit Open",["lore"]="Silencing one mechanism does not resolve the house.",["number"]=36},{["id"]="route",["category"]="Basement",["name"]="The Measured Way Out",["requirements"]={["items"]={"record2"},["flags"]={"route"}},["description"]="You follow the marked distances to the stairs. Your final measurement leaves a person-sized space unaccounted for.",["achievement"]="Keep the Measure",["lore"]="Physical records can be useful and still incomplete.",["number"]=37},{["id"]="seal",["category"]="Basement",["name"]="Maintained in Absence",["requirements"]={["items"]={"letter1"},["flags"]={"seal","valve"}},["description"]="You renew the inspection seal. By morning the signature beneath yours has been freshly added.",["achievement"]="Seal Renewed",["lore"]="An omitted place may still receive care.",["number"]=38},{["id"]="leave-open",["category"]="Basement",["name"]="Leave the Light On",["requirements"]={["items"]={"key-chamber"},["flags"]={"power","door"}},["description"]="You unlock the chamber and leave its light burning. Nobody comes out while you are watching.",["achievement"]="An Open Invitation",["lore"]="Offers hospitality without identifying an occupant.",["number"]=39},{["id"]="bind",["category"]="Memory",["name"]="A Book with Both Hands",["requirements"]={["diary"]=20,["flags"]={"bind"}},["description"]="You bind both kinds of handwriting into one volume. The last blank page remains blank until you close the cover.",["achievement"]="Both Hands",["lore"]="Refuses to declare either narrator authentic.",["number"]=40},{["id"]="contradictions",["category"]="Memory",["name"]="Two Originals",["requirements"]={["records"]=4,["flags"]={"compare"}},["description"]="You file both originals. The drawer accepts them without resistance. For once, you do not choose which version deserves to exist.",["achievement"]="Keep Both Copies",["lore"]="Contradictory evidence can coexist.",["number"]=41},{["id"]="names-kept",["category"]="Memory",["name"]="Names Without Faces",["requirements"]={["items"]={"record3","letter2"},["flags"]={"names"}},["description"]="You write the names without inventing faces. At dinner Mum recognises one spelling and crosses out nothing.",["achievement"]="Leave the Faces Blank",["lore"]="Distinguishes preserving evidence from manufacturing certainty.",["number"]=42},{["id"]="blank",["category"]="Memory",["name"]="The Unwritten Page",["requirements"]={["diary"]=12,["flags"]={"blank"}},["description"]="You leave a page for the person who cannot yet be described. In the quiet, a pen rolls toward it and stops.",["achievement"]="Leave a Margin",["lore"]="Makes room for unresolved identity.",["number"]=43},{["id"]="extra-seat",["category"]="Anomaly",["name"]="The Patient Guest",["requirements"]={["anomalies"]={"chair"},["flags"]={"places"}},["description"]="You sit beside the extra chair until morning. Its seat cools at exactly the moment yours does.",["achievement"]="Wait Beside It",["lore"]="An anomaly offers companionship rather than a pursuer.",["number"]=44},{["id"]="answer",["category"]="Anomaly",["name"]="One Knock More",["requirements"]={["anomalies"]={"pipe"},["flags"]={"answer"}},["description"]="You return the additional beat. The response comes from the ordinary hallway, at the height of a child’s hand.",["achievement"]="Return the Beat",["lore"]="Connects infrastructure to domestic memory without proving a cause.",["number"]=45},{["id"]="glass-guest",["category"]="Anomaly",["name"]="The Far Side of the Glass",["requirements"]={["anomalies"]={"glass","frost"},["flags"]={"glass"}},["description"]="You cover the observation pane. The covered surface reflects a room you are not standing in.",["achievement"]="Stop Observing",["lore"]="Questions the act of watching and recording.",["number"]=46},{["id"]="follow-step",["category"]="Anomaly",["name"]="Walk at Their Pace",["requirements"]={["anomalies"]={"steps","scale"},["flags"]={"route"}},["description"]="You let the second footfall set your pace. The stairs return you to an unfamiliar arrangement of familiar furniture.",["achievement"]="A Shared Pace",["lore"]="A path may be shared without identifying a companion.",["number"]=47},{["id"]="steady",["category"]="Sanity",["name"]="A Carefully Kept Morning",["requirements"]={["diary"]=8,["sanityMin"]=80,["flags"]={"rest"}},["description"]="You put the evidence down, eat and wait for daylight. The questions remain. You are able to ask them tomorrow.",["achievement"]="Return Tomorrow",["lore"]="Self-preservation is a valid ending.",["number"]=48},{["id"]="uncertain",["category"]="Sanity",["name"]="An Honest Uncertainty",["requirements"]={["records"]=3,["sanityMin"]=35,["sanityMax"]=65,["flags"]={"compare"}},["description"]="You label the file UNCONFIRMED. The letters do not rearrange themselves. That is all the reassurance you ask for.",["achievement"]="Unconfirmed",["lore"]="Sanity is not a truth detector.",["number"]=49},{["id"]="anchor",["category"]="Sanity",["name"]="One Thing You Know",["requirements"]={["items"]={"memory1","memory2"},["sanityMax"]=25,["sanityMin"]=1,["flags"]={"anchor"}},["description"]="You hold one ordinary memory through the last of the distortion. A hand steadies yours. You do not turn to see whose.",["achievement"]="Hold One Memory",["lore"]="Distress never makes an interpretation definitively true.",["number"]=50},{["id"]="diarist",["category"]="Collector",["name"]="Every Page Accounted For",["requirements"]={["diary"]=20},["description"]="You number the twenty pages. The binding has room for twenty-one. You leave the extra space in the catalogue.",["achievement"]="The Unfinished Volume",["lore"]="Completeness of a collection is not completeness of history.",["number"]=51},{["id"]="family-file",["category"]="Collector",["name"]="The Household File",["requirements"]={["photos"]=6,["records"]=6},["description"]="You assemble a family file. Its contents disagree. Its cover can hold them all.",["achievement"]="Family Archivist",["lore"]="Records preserve a larger household, not a certified family tree.",["number"]=52},{["id"]="drawings",["category"]="Collector",["name"]="The Wall at Their Height",["requirements"]={["drawings"]=5,["flags"]={"beds"}},["description"]="You hang every drawing at the height of its maker. One hangs above the height marks; another below the skirting.",["achievement"]="At Their Height",["lore"]="The children cannot be arranged into a reliable chronology.",["number"]=53},{["id"]="fragments",["category"]="Collector",["name"]="Nothing Discarded",["requirements"]={["memories"]=8,["letters"]=4},["description"]="You take every fragment to the stairs. Upstairs, a box waits with your handwriting and no date.",["achievement"]="Nothing Discarded",["lore"]="Collection leads to another possible history, not a final solution.",["number"]=54},{["id"]="zero",["category"]="Secret",["name"]="The Room Number Nobody Used",["requirements"]={["items"]={"record4","key-observation"},["anomalies"]={"label"},["flags"]={"zero"}},["description"]="You enter zero in the inventory. A door clicks shut elsewhere. The corridor still contains the same number of openings.",["achievement"]="Room Zero",["lore"]="An absent number may refer to a person, a space or an accounting error.",["number"]=55},{["id"]="draft",["category"]="Secret",["name"]="An Unsigned Father",["requirements"]={["dad"]=6,["flags"]={"letters"}},["description"]="You leave the final letter unsigned. Mum calls it his handwriting, then asks whose desk you found it in.",["achievement"]="Unsigned",["lore"]="Keeps the father hypothesis unsettled.",["number"]=56},{["id"]="wrong-birthday",["category"]="Secret",["name"]="Candles Without a Cake",["requirements"]={["items"]={"diary12","photo4","drawing3"},["flags"]={"candles"}},["description"]="You light the unclaimed candles. Wax falls in four separate pools. Nobody says a birthday wish aloud.",["achievement"]="An Unclaimed Birthday",["lore"]="A shared ritual outlasts its explanation.",["number"]=57},{["id"]="listen-wall",["category"]="Secret",["name"]="A Place in the Wall",["requirements"]={["anomalyCount"]=10,["items"]={"letter3"},["flags"]={"listen"}},["description"]="You spend a night listening to the wall. In the morning a recording contains only your own careful breathing.",["achievement"]="Listen Without Naming",["lore"]="Questions whether the listener contributes to the haunting.",["number"]=58},{["id"]="inventory-open",["category"]="True Mystery",["name"]="The Inventory Remains Open",["requirements"]={["diary"]=20,["records"]=6,["flags"]={"compare","door"}},["description"]="You leave the household inventory open. One column is headed PRESENT. The other has no heading. Neither column stays empty.",["achievement"]="An Open Inventory",["lore"]="The central family question remains deliberately unanswered.",["number"]=59},{["id"]="no-correction",["category"]="True Mystery",["name"]="Do Not Correct the House",["requirements"]={["anomalyCount"]=25,["flags"]={"blank","route"}},["description"]="You preserve every version of the plan. The house is quieter when it is no longer being asked to agree with you.",["achievement"]="No Correction Necessary",["lore"]="Observation changes the relationship, not the certainty of the lore.",["number"]=60},{["id"]="tomorrow",["category"]="True Mystery",["name"]="Somewhere for Tomorrow",["requirements"]={["diary"]=20,["memories"]=8,["flags"]={"mum","bind","blank"}},["description"]="You leave the last page unfinished. At breakfast Mum asks whether you slept well. For once you tell her about a dream instead of supplying an answer.",["achievement"]="Somewhere for Tomorrow",["lore"]="Begins a new era while leaving the family mystery open.",["number"]=61}}},["deepItems"]={{["id"]="diary1",["number"]=1,["title"]="The long table",["text"]="Mum made toast and Dad drew a boat in the butter. We argued about who got the crooked slice. I counted four cups before anyone sat down. I am writing that because I always forget ordinary things.",["type"]="diary",["room"]="storage"},{["id"]="diary2",["number"]=2,["title"]="Our marks",["text"]="We measured ourselves by the kitchen door. Mine is the bent line. The straight one belongs to the person who insists they are taller. Dad wrote the date twice because the first date looked wrong.",["type"]="diary",["room"]="storage"},{["id"]="diary3",["number"]=3,["title"]="Saturday rain",["text"]="We made a tent from two sheets. Mum said not to block the hallway. Someone kept putting a fourth cushion inside. We left it there. It made a good roof support.",["type"]="diary",["room"]="boiler"},{["id"]="diary4",["number"]=4,["title"]="The school photograph",["text"]="Our class photographs came home. There are two envelopes with our surname and one with no name. Mum put the empty one in the drawer before I could see whether it was empty.",["type"]="diary",["room"]="boiler"},{["id"]="diary5",["number"]=5,["title"]="Dad’s coat",["text"]="Dad let me carry his coat upstairs. It smelled of rain and the workshop. The pockets were full of small screws. One pocket had a key labelled RETURN, though I do not know what it returns.",["type"]="diary",["room"]="tunnel"},{["id"]="diary6",["number"]=6,["title"]="The other bed",["text"]="We swapped beds after the argument about the window. In the morning everybody said there had only ever been one bed. The floor is still lighter where the other feet stood.",["type"]="diary",["room"]="tunnel"},{["id"]="diary7",["number"]=7,["title"]="The room at the end",["text"]="There is a room at the end of the hall. I thought it belonged to our visitor. Nobody remembers inviting a visitor. Mum told me to leave the clean towel outside it anyway.",["type"]="diary",["room"]="archive"},{["id"]="diary8",["number"]=8,["title"]="Knocking practice",["text"]="Three knocks mean come in. Two mean wait. Tonight someone knocked twice from the wall beside my pillow. I waited. It seems rude to leave someone waiting, even if there is no door.",["type"]="diary",["room"]="archive"},{["id"]="diary9",["number"]=9,["title"]="A quiet argument",["text"]="Dad said keeping a room was not the same as keeping a person. Mum said he had agreed before. They stopped when I entered. There were four unfinished cups on the table, all still warm.",["type"]="diary",["room"]="family"},{["id"]="diary10",["number"]=10,["title"]="The spare name",["text"]="My report has a name crossed out beneath mine. The teacher says she never wrote it. Her pen left the same little hook on every letter. I have copied the hook here so it cannot disappear.",["type"]="diary",["room"]="family"},{["id"]="diary11",["number"]=11,["title"]="Yesterday’s drawing",["text"]="My drawing has changed. I remember giving the tall person five fingers. Now the tall person is a door, but the hand is still there. Mum says I have always drawn buildings.",["type"]="diary",["room"]="study"},{["id"]="diary12",["number"]=12,["title"]="Someone’s birthday",["text"]="We lit candles without a cake. Mum said it was not a birthday. Dad could not remember why he had bought the candles. There are marks on the table from a cake tin that will not fit our cupboard.",["type"]="diary",["room"]="study"},{["id"]="diary13",["number"]=13,["title"]="The missing pronoun",["text"]="I wrote WE WENT HOME. This morning it says I WENT HOME. The space is too wide for I. I keep trying to remember whose hand I was holding, and remembering a different sleeve.",["type"]="diary",["room"]="sealed"},{["id"]="diary14",["number"]=14,["title"]="A longer landing",["text"]="It took seventeen steps to reach the bathroom. I counted twelve on the way back. Dad marked the wall with tape. In the evening the tape was wrapped around his wrist like he had always worn it.",["type"]="diary",["room"]="sealed"},{["id"]="diary15",["number"]=15,["title"]="The voice downstairs",["text"]="Someone read my first page aloud from underneath the floor. They made the same mistake over the word crooked. I do not remember writing that mistake. I do remember being corrected.",["type"]="diary",["room"]="observation"},{["id"]="diary16",["number"]=16,["title"]="Our own handwriting",["text"]="There are two kinds of handwriting in this book. The second kind calls the first kind a liar. Both make the same spelling mistakes. I am leaving the mistakes where they are.",["type"]="diary",["room"]="observation"},{["id"]="diary17",["number"]=17,["title"]="The person in the photograph",["text"]="Dad is missing from one photograph. In the next he is holding the camera, though I can see both his hands in the picture. Mum knows which coat was his. She cannot say what he looked like.",["type"]="diary",["room"]="children"},{["id"]="diary18",["number"]=18,["title"]="A room set aside",["text"]="We carried boxes to the room that is not on the plan. I remember doing it alone. My arms hurt in four places, as if someone else had been holding the same box.",["type"]="diary",["room"]="children"},{["id"]="diary19",["number"]=19,["title"]="If you find this",["text"]="If you find this, do not decide too quickly who I was. I have been your sibling in some memories and your visitor in others. The room remembers a name. It will not tell me whether the name was mine.",["type"]="diary",["room"]="chamber"},{["id"]="diary20",["number"]=20,["title"]="An ordinary morning",["text"]="Today we had toast. Someone asked for the crooked slice. There were places for everybody, which is not the same as knowing how many people there were. Please leave this page unfinished. I would like tomorrow to have somewhere to go.",["type"]="diary",["room"]="chamber"},{["id"]="dad1",["type"]="dad",["title"]="Dad’s notes · 1",["text"]="A coat repair receipt signed D. The same initials label a child’s school bag.",["room"]="storage"},{["id"]="dad2",["type"]="dad",["title"]="Dad’s notes · 2",["text"]="A service note: “Keep the heating on. Leave the fourth branch isolated.”",["room"]="archive"},{["id"]="dad3",["type"]="dad",["title"]="Dad’s notes · 3",["text"]="An unfinished letter begins Dear children. The next draft begins Dear child.",["room"]="sealed"},{["id"]="dad4",["type"]="dad",["title"]="Dad’s notes · 4",["text"]="A workshop list includes three small stools and one adult chair. None were collected.",["room"]="storage"},{["id"]="dad5",["type"]="dad",["title"]="Dad’s notes · 5",["text"]="A folded timetable has a return journey pencilled in on an impossible date.",["room"]="archive"},{["id"]="dad6",["type"]="dad",["title"]="Dad’s notes · 6",["text"]="Two final drafts share the same signature stroke. Only one is signed Dad.",["room"]="sealed"},{["id"]="photo1",["type"]="photo",["title"]="Family photographs · 1",["text"]="Four places at a long table. The fourth person is outside the frame.",["room"]="boiler"},{["id"]="photo2",["type"]="photo",["title"]="Family photographs · 2",["text"]="Two children standing by a bed. A crease runs through both their faces.",["room"]="family"},{["id"]="photo3",["type"]="photo",["title"]="Family photographs · 3",["text"]="A raincoat hangs beside a taller figure whose face is turned away.",["room"]="observation"},{["id"]="photo4",["type"]="photo",["title"]="Family photographs · 4",["text"]="Candles reflected in a window. There is no cake in the photograph.",["room"]="boiler"},{["id"]="photo5",["type"]="photo",["title"]="Family photographs · 5",["text"]="The family house with one more window. The negative has fewer windows.",["room"]="family"},{["id"]="photo6",["type"]="photo",["title"]="Family photographs · 6",["text"]="An empty room. The handwritten caption says All of us, home at last.",["room"]="observation"},{["id"]="drawing1",["type"]="drawing",["title"]="Lost drawings · 1",["text"]="Two narrow beds, one red and one blue. Both have the same name beneath them.",["room"]="tunnel"},{["id"]="drawing2",["type"]="drawing",["title"]="Lost drawings · 2",["text"]="A family with joined hands. One hand belongs to the border of the page.",["room"]="study"},{["id"]="drawing3",["type"]="drawing",["title"]="Lost drawings · 3",["text"]="A cake drawn around four candles. The birthday name has been carefully erased.",["room"]="children"},{["id"]="drawing4",["type"]="drawing",["title"]="Lost drawings · 4",["text"]="A tall figure watering a garden. The watering can is labelled MUM.",["room"]="tunnel"},{["id"]="drawing5",["type"]="drawing",["title"]="Lost drawings · 5",["text"]="Five windows on a wall measured for four. Something waves from the space between them.",["room"]="study"},{["id"]="record1",["type"]="record",["title"]="Family records · 1",["text"]="A household list with four entries. Its certified copy has two. Neither is marked amended.",["room"]="archive"},{["id"]="record2",["type"]="record",["title"]="Family records · 2",["text"]="A survey records thirty steps. A second measurement records twenty-five with identical end marks.",["room"]="sealed"},{["id"]="record3",["type"]="record",["title"]="Family records · 3",["text"]="Three names appear on a school contact form. The telephone number is the house’s own.",["room"]="storage"},{["id"]="record4",["type"]="record",["title"]="Family records · 4",["text"]="Room 0: inspected, occupied, no key issued. A later line reads Never allocated.",["room"]="archive"},{["id"]="record5",["type"]="record",["title"]="Family records · 5",["text"]="A birth-date column has been cut from an otherwise undamaged ledger.",["room"]="sealed"},{["id"]="record6",["type"]="record",["title"]="Family records · 6",["text"]="Two originals of a household inventory. PRESENT is the only column heading that survives.",["room"]="storage"},{["id"]="letter1",["type"]="letter",["title"]="Secret letters · 1",["text"]="“Keep the seal intact, even if we cannot agree who it protects.” No signature.",["room"]="family"},{["id"]="letter2",["type"]="letter",["title"]="Secret letters · 2",["text"]="“Do not give them faces just because the names sound familiar.”",["room"]="observation"},{["id"]="letter3",["type"]="letter",["title"]="Secret letters · 3",["text"]="“Listen before you decide it is asking to be let out.” The envelope is addressed inward.",["room"]="boiler"},{["id"]="letter4",["type"]="letter",["title"]="Secret letters · 4",["text"]="“I left enough room for tomorrow.” The date is written in two hands.",["room"]="family"},{["id"]="memory1",["type"]="memory",["title"]="Memory fragments · 1",["text"]="A warm sleeve against your cheek. You cannot decide whether you were being carried or carrying someone.",["room"]="study"},{["id"]="memory2",["type"]="memory",["title"]="Memory fragments · 2",["text"]="Two hands holding the same heavy box. You remember four aching arms.",["room"]="children"},{["id"]="memory3",["type"]="memory",["title"]="Memory fragments · 3",["text"]="A voice saying your childhood nickname from the opposite side of a classroom door.",["room"]="tunnel"},{["id"]="memory4",["type"]="memory",["title"]="Memory fragments · 4",["text"]="The smell of wet wool and a workshop you cannot place.",["room"]="study"},{["id"]="memory5",["type"]="memory",["title"]="Memory fragments · 5",["text"]="An argument over the window-side bed, followed by an apology nobody remembers making.",["room"]="children"},{["id"]="memory6",["type"]="memory",["title"]="Memory fragments · 6",["text"]="Mum cutting one extra slice of toast and looking surprised by the knife.",["room"]="tunnel"},{["id"]="memory7",["type"]="memory",["title"]="Memory fragments · 7",["text"]="A pencil marking a height above your head. The hand holding it is smaller than yours.",["room"]="study"},{["id"]="memory8",["type"]="memory",["title"]="Memory fragments · 8",["text"]="An ordinary morning that feels shared, without giving you a reliable headcount.",["room"]="children"},{["id"]="key-archive",["type"]="key",["room"]="storage",["title"]="Flat-file key",["text"]="A small brass key. Its tag refers to the archive. The tooth pattern has been corrected by hand."},{["id"]="key-study",["type"]="key",["room"]="archive",["title"]="Drafting-desk key",["text"]="A small brass key. Its tag refers to the hidden study. The tooth pattern has been corrected by hand."},{["id"]="key-observation",["type"]="key",["room"]="tunnel",["title"]="Inspection-window key",["text"]="A small brass key. Its tag refers to the observation room. The tooth pattern has been corrected by hand."},{["id"]="key-chamber",["type"]="key",["room"]="children",["title"]="Unnumbered chamber key",["text"]="A small brass key. Its tag refers to a room without a number. The tooth pattern has been corrected by hand."}},["deepActions"]={["storage"]={{"rest","Put the evidence down","You give yourself permission to return tomorrow. Resting does not erase the evidence."},{"anchor","Hold an ordinary memory","You keep one ordinary memory close without deciding whose memory it was."}},["boiler"]={{"valve","Isolate the knocking pipe","The labelled valve closes. The pressure gauge settles safely."},{"power","Switch on auxiliary lighting","The isolated lighting circuit comes on. The heating branch remains separate."},{"answer","Return the extra beat","You tap the additional beat against a cold pipe."}},["tunnel"]={{"route","Mark the measured route","You mark the same physical route in chalk. Its real distance will not change beneath your feet."},{"zero","Record room zero","You copy the unused number without assigning it to a person."}},["archive"]={{"compare","Keep both originals","You file both contradictory records. Neither is declared a mistake."},{"names","Copy names without faces","You copy the names and leave their photographs unassigned."}},["family"]={{"places","Set every suggested place","You set places for the household suggested by the evidence. One spare chair remains nearby."},{"listen","Listen to the disconnected radio","The radio is unplugged. You leave it that way and listen."}},["study"]={{"letters","Arrange the unsigned drafts","The drafts remain unsigned. You place the coat beside them."},{"bind","Bind both kinds of handwriting","You preserve both hands in the same diary."},{"blank","Leave the last page unfinished","There is somewhere for tomorrow to go."}},["sealed"]={{"seal","Renew the inspection seal","You add a fresh date without removing the earlier signatures."},{"listen","Listen without naming it","You listen without calling the sound a particular person."}},["observation"]={{"glass","Cover the observation pane","You cover the pane, leaving the people it might have shown unobserved."}},["children"]={{"beds","Make both beds","Both beds receive clean sheets. You do not choose who slept where."},{"candles","Light the unclaimed candles","Four candles burn beside an empty plate."}},["chamber"]={{"door","Leave the chamber door open","You leave the ordinary door open. Nothing is required to walk through it."}}},["deepEndRoom"]={["Family"]="family",["Basement"]="boiler",["Memory"]="archive",["Anomaly"]="observation",["Sanity"]="storage",["Collector"]="study",["Secret"]="sealed",["True Mystery"]="chamber"},["cityPlaces"]={{["id"]="station",["name"]="Last Train Station",["color"]="#5e6c68",["clue"]="The ticket has tomorrow’s date. The departure board lists your childhood address.",["choices"]={{"Board the last train","The passenger","You board the train. Every passenger has your face at a different age. At the next stop, you finally recognise the person waiting for you."},{"Take the signal operator’s chair","The signal keeper","You change the signal to red. The train never arrives at the house. Every night, you keep one more family from boarding."}},["x"]=-80,["z"]=-170},{["id"]="library",["name"]="Municipal Archives",["color"]="#776d57",["clue"]="The register lists your death on every page. One blank line remains beneath Mother’s name.",["choices"]={{"Erase your entry","The unwritten","You erase your entry from the register. Outside, nobody remembers the house. You do not remember it either—until you find the key in your pocket."},{"Sign as the new archivist","The archivist","You sign your name at the desk. The books settle. Every lost child has a place in the catalogue now. One shelf is reserved for you."}},["x"]=-40,["z"]=-170},{["id"]="cinema",["name"]="Orpheum Cinema",["color"]="#69565a",["clue"]="The projector plays your kitchen. On screen, Mother is about to open the spare room.",["choices"]={{"Cut the final reel","The missing scene","You cut the film before the door opens. The screen turns white. When you walk home, the hallway ends where it always should have."},{"Step into the screen","The understudy","You step into the picture. Mother looks up from the kitchen table. Somewhere behind you, an audience begins to applaud."}},["x"]=0,["z"]=-170},{["id"]="clinic",["name"]="St Agnes Clinic",["color"]="#69766b",["clue"]="A case file describes a patient split into a memory and a body. The consent form is unsigned.",["choices"]={{"Destroy the case file","Discharged","You destroy the file. The ward doors unlock. You and Mother leave together, but the scar on your palm has two lifelines."},{"Accept the offered treatment","The quiet ward","You sign the consent form. Your fear disappears first. Then your name. A nurse closes the curtains around a bed that has always been yours."}},["x"]=40,["z"]=-170},{["id"]="chapel",["name"]="Chapel of the Echo",["color"]="#736b61",["clue"]="The bell has no clapper. A prayer tucked inside says: “Speak the name you were given before the room.”",["choices"]={{"Ring the bell with your voice","The returned name","You speak your own name into the bell. The city answers in Mother’s voice. Every locked door opens, and none of them lead back to the spare room."},{"Stay for the midnight vigil","The last candle","You light the final candle. The shadows kneel around you. You promise to keep the light burning until every forgotten child comes home."}},["x"]=80,["z"]=-170},{["id"]="radio",["name"]="North Street Radio",["color"]="#5f677b",["clue"]="The emergency frequency repeats a warning in your voice. A second microphone is warm.",["choices"]={{"Broadcast a warning","The warning","You warn the city never to open an unfamiliar door. All around you, radios click off. At home, Mother puts down the spare key."},{"Answer the voice on air","The transmission","“I’m here,” you say. Your voice escapes through every radio in the city. You can never return to your body, but no one will be alone in the house again."}},["x"]=-80,["z"]=-210},{["id"]="cafe",["name"]="The Wakeful Cafe",["color"]="#82705b",["clue"]="Three cups are warm. The receipt says you have been sitting here since Tuesday.",["kind"]="cafe",["choices"]={},["x"]=-40,["z"]=-210},{["id"]="laundry",["name"]="Pale Street Laundry",["color"]="#70837d",["clue"]="A machine turns without water. Inside, your school uniform is still your size.",["kind"]="laundry",["choices"]={},["x"]=0,["z"]=-210},{["id"]="postoffice",["name"]="Dead Letter Office",["color"]="#826952",["clue"]="The undelivered letters are all addressed to the upstairs records room.",["kind"]="post",["choices"]={},["x"]=40,["z"]=-210},{["id"]="workshop",["name"]="Hollow Clock Repairs",["color"]="#717d78",["clue"]="Every clock runs normally until you look away. One ticks inside a locked drawer.",["kind"]="workshop",["choices"]={},["x"]=80,["z"]=-210},{["id"]="florist",["name"]="Night Bloom Florist",["color"]="#758367",["clue"]="Someone ordered flowers for your return. The delivery date is tomorrow.",["kind"]="florist",["choices"]={},["x"]=-80,["z"]=-250},{["id"]="bakery",["name"]="Ash and Honey Bakery",["color"]="#8d7860",["clue"]="The oven is cold. A loaf on the counter is breathing slowly.",["kind"]="bakery",["choices"]={},["x"]=-40,["z"]=-250},{["id"]="apartments",["name"]="Number Nine Flats",["color"]="#747780",["clue"]="The tenants list contains your name twenty times. Each signature is different.",["kind"]="apartments",["choices"]={},["x"]=0,["z"]=-250},{["id"]="hotel",["name"]="Hotel Afterimage",["color"]="#816e72",["clue"]="The guest book says you checked in with Mother. There is no departure column.",["kind"]="hotel",["choices"]={},["x"]=40,["z"]=-250},{["id"]="market",["name"]="Empty Sunday Market",["color"]="#7e805f",["clue"]="The stalls sell objects you lost as a child. One vendor has your missing tooth.",["kind"]="market",["choices"]={},["x"]=80,["z"]=-250},{["id"]="greenhouse",["name"]="Glasshouse Gardens",["color"]="#617968",["clue"]="The plants lean away from the sun and towards the spare-room key in your pocket.",["kind"]="greenhouse",["choices"]={},["x"]=-80,["z"]=-290},{["id"]="waterworks",["name"]="Stillwater Pump House",["color"]="#627b80",["clue"]="The gauge pulses like a heartbeat. Through the pipes, someone whispers your address.",["kind"]="waterworks",["choices"]={},["x"]=-40,["z"]=-290},{["id"]="garage",["name"]="End of Road Garage",["color"]="#7a7665",["clue"]="A car waits with its engine off. In the rear-view mirror, the driver is still here.",["kind"]="garage",["choices"]={},["x"]=0,["z"]=-290},{["id"]="bookshop",["name"]="Second Hand Stories",["color"]="#7e6c63",["clue"]="Every book has the same last sentence: please do not leave me in that room.",["kind"]="books",["choices"]={},["x"]=40,["z"]=-290},{["id"]="playground",["name"]="The Empty Playroom",["color"]="#7f7b69",["clue"]="The rocking horse moves once. Through the glass you see no hand that pushed it.",["kind"]="playroom",["choices"]={},["x"]=80,["z"]=-290}},["residents"]={{["id"]="chapel",["name"]="The candle keeper",["x"]=24,["z"]=-22.5,["coat"]="#756b59",["phase"]=0},{["id"]="radio",["name"]="The engineer",["x"]=42,["z"]=-21.574381916711314,["coat"]="#4e6970",["phase"]=1},{["id"]="clinic",["name"]="The night nurse",["x"]=24,["z"]=-39.49977283049175,["coat"]="#775857",["phase"]=2},{["id"]="library",["name"]="The archivist",["x"]=24,["z"]=-58.34476799113415,["coat"]="#668071",["phase"]=3},{["id"]="station",["name"]="The porter",["x"]=42,["z"]=-59.33248274483872,["coat"]="#827754",["phase"]=4},{["id"]="cinema",["name"]="The projectionist",["x"]=6,["z"]=-77.55481670212946,["coat"]="#66647d",["phase"]=5}},["legacy"]={["advancedEndings"]={["grid"]={"Ending 25 · A city with its lights on","You isolate the circuit feeding the spare room. Along every street, the lamps brighten. Mother calls from a house with one fewer door."},["dawn"]={"Ending 26 · The first bus home","You sit beside the porter and wait until daylight. When the next bus arrives, the passengers are ordinary strangers. For once, nobody knows your name."},["witness"]={"Ending 27 · The witness","You watch the film, then tell the archivist exactly what you saw. This time, there is a witness outside the house. Mother can no longer be made to forget."},["keeper"]={"Ending 28 · Keep the door closed","You choose to remain, with a warning on the fuse box and the lantern beside the door. The house does not stop whispering. You learn when not to listen."}},["noteDefs"]={{["id"]="note1",["p"]={1.38,1.45,3.8},["axis"]="x",["title"]="BEFORE YOU LEAVE",["text"]="The gate knows three words.\nFirst: WE.\nDo not knock back."},{["id"]="note2",["p"]={-6.13,1.05,8.5},["axis"]="x",["title"]="DON’T FEED IT",["text"]="Second: WERE.\nThe sandwiches appear because\nsomeone keeps setting your place."},{["id"]="note3",["p"]={2.8,1.65,17.87},["axis"]="z",["title"]="COUNT THE CHAIRS",["text"]="Third: HERE.\nSay all three at the garden gate.\nTake nobody’s reflection with you."},{["id"]="note4",["p"]={-5.8,1.5,-8.87},["axis"]="z",["title"]="THE GARDENER",["text"]="Turn the music box in the shed.\nTake its lullaby to the well.\nDo not look down while it sings."},{["id"]="note5",["p"]={8.88,1.4,-7},["axis"]="x",["title"]="PLEASE REMEMBER",["text"]="If every note is found,\nwrite your own name in the diary.\nYou are allowed to be whole."},{["id"]="note6",["p"]={4.2,0.45,2.12},["axis"]="z",["title"]="UNDER THE MIRROR",["text"]="The glass remembers the room.\nSometimes it remembers someone\nwho is no longer standing there."}},["endings"]={["truth"]={["title"]="Ending IV · Both our names",["text"]="Mother steps into the room beside you. She tells the child everything she made herself forget.\nThe walls loosen like a held breath. Two voices become one.\nAt breakfast, there are three places at the table.",["flags"]={"truth"}},["escape"]={["title"]="Ending V · Outside",["text"]="The telephone rings once. You take Mother’s hand and open the front door.\nBeyond it is a street you recognise. At every window stands your reflection.\nYou keep walking.",["flags"]={"called","power"}},["ward"]={["title"]="Ending VI · The keeper",["text"]="The mirror steps across the chalk circle. It takes the diary and all the memories it contains.\n“Someone must keep them,” it says.\nYou and Mother leave. At night, every mirror in your new home faces the wall.",["flags"]={"mirror","ward"}},["gate"]={["title"]="Ending VII · We were here",["text"]="You speak the three words. The gate opens onto a morning that has not happened yet.\nThe house calls after you in Mother’s voice. This time, you do not answer.",["flags"]={"note1","note2","note3","gateWords"}},["well"]={["title"]="Ending VIII · The lullaby below",["text"]="The music box sings into the well. A child finishes the song from somewhere far beneath the water.\nWhen you return to the house, the spare room is a cupboard.\nEvery night, a new flower grows beside the well.",["flags"]={"note4","music","wellQuiet"}},["whole"]={["title"]="Ending IX · Your own handwriting",["text"]="You write your own name over both names in the diary.\nThe mirror cracks without breaking. Mother remembers a single child, with every memory intact.\nThe sticky notes disappear. You leave one of your own: “We got out.”",["flags"]={"note1","note2","note3","note4","note5","note6","truth","mirror"}},["morning"]={["title"]="Ending X · A garden for tomorrow",["text"]="At dawn, every flower faces the house. You invite Mother outside.\nShe names the flowers instead of naming the things she lost.\nFor the first time, the diary has no entry for tomorrow.",["flags"]={"planted","wellQuiet"}},["burial"]={["title"]="Ending XI · What the earth keeps",["text"]="You leave the memory beneath the roots. The spare room fills with the smell of rain.\nMother remembers love without remembering the room.\nEvery autumn, you find one small brass leaf beneath the tree.",["flags"]={"buried","note4"}},["light"]={["title"]="Ending XII · Your own shadow",["text"]="The lantern lights a path beyond the garden. You follow the shadow that moves exactly when you do.\nBehind you, the house keeps calling your name.\nYou let the flame answer.",["flags"]={"lantern","note5"}},["grid"]={["title"]="Ending 25 · A city with its lights on",["text"]="You isolate the circuit feeding the spare room. Along every street, the lamps brighten. Mother calls from a house with one fewer door.",["flags"]={"power"}},["dawn"]={["title"]="Ending 26 · The first bus home",["text"]="You sit beside the porter and wait until daylight. When the next bus arrives, the passengers are ordinary strangers. For once, nobody knows your name.",["flags"]={"venue:station"}},["witness"]={["title"]="Ending 27 · The witness",["text"]="You watch the film, then tell the archivist exactly what you saw. This time, there is a witness outside the house. Mother can no longer be made to forget.",["flags"]={"projectorSeen","venue:library"}},["keeper"]={["title"]="Ending 28 · Keep the door closed",["text"]="You choose to remain, with a warning on the fuse box and the lantern beside the door. The house does not stop whispering. You learn when not to listen.",["flags"]={"lantern","truth"}},["burn"]={["title"]="Ending I · An empty room",["text"]="The photograph and recording prove that you were here. You burn the diary. The door becomes a patch of wallpaper.\nMother finally says your name.\nThat night, you hear a child crying inside the wall.",["flags"]={"tomorrowDiary"}},["enter"]={["title"]="Ending II · The remembered",["text"]="You enter the room. The figure has your face at seven years old.\n“I kept everything you couldn’t bear,” it says.\nYou sit beside it. Downstairs, Mother calls both your names.\nFor the first time, you answer together.",["flags"]={"tomorrowDiary"}},["release"]={["title"]="Ending III · The spare",["text"]="You unlock the door. Someone wearing your face walks downstairs.\nMother embraces them. “You’re finally home.”\nYou try to follow, but the hallway ends at a bedroom. On its desk is a diary.\nYou pick up the pen.",["flags"]={"tomorrowDiary"}}}}}
